    handleCut,
    handlePaste,
    handleDuplicate,
    handleGroupElements,
    handleUngroupElement,
    handleDelete,
    handleFlip,
    handleAlignElements,
    handleDistributeElements,
    canDistribute,
    selectionGroupable,
    handleMoveLayer,
    handleMoveLayerToEdge,
    handleMergeShapes,
    canMergeShapes,
    handleContextMenuAction
