// src/viewer/utils/export-helpers.ts
async function renderElementToCanvas(element, scale = 2, backgroundColor) {
  const canvas = await renderToCanvas(element, {
    scale,
    useCORS: true,
    allowTaint: true,
    backgroundColor: backgroundColor ?? null,
    logging: false,
    // Ignore elements that interfere with export (selection overlays, snap lines, etc.)
    ignoreElements: (el) => {
      const htmlEl = el;
      if (htmlEl.dataset?.exportIgnore === "true") {
        return true;
      }
      if (htmlEl.classList?.contains("pointer-events-none") && (htmlEl.classList.contains("z-50") || htmlEl.classList.contains("z-[60]"))) {
        return true;
      }
      return false;
    }
  });
  return canvas;
}
