// src/viewer/utils/export-video.ts
async function exportAllSlidesAsVideo(slideStageRef, totalSlides, setActiveSlide, currentSlideIndex, options = {}) {
  const {
    scale = 1,
    slideDurationMs = 3e3,
    slideTimingsMs,
    onProgress,
    onRecordProgress,
    signal
  } = options;
  const slideCanvases = [];
  for (let i = 0; i < totalSlides; i++) {
    if (signal?.aborted) {
      throw new DOMException("Export cancelled", "AbortError");
    }
    onProgress?.(i, totalSlides);
    setActiveSlide(i);
    await waitForRender(150);
    const stageEl = slideStageRef.current;
    if (!stageEl) {
      console.warn(`[export] Could not find slide stage element for slide ${i}`);
      continue;
    }
    const canvas = await renderElementToCanvas(stageEl, scale);
    slideCanvases.push(canvas);
  }
  setActiveSlide(currentSlideIndex);
  if (slideCanvases.length === 0) {
    throw new Error(translationsEn["pptx.export.errorNoSlidesVideo"]);
  }
  const firstCanvas = slideCanvases[0];
  const recordingCanvas = document.createElement("canvas");
  recordingCanvas.width = firstCanvas.width;
  recordingCanvas.height = firstCanvas.height;
  const ctx = recordingCanvas.getContext("2d");
  if (!ctx) {
    throw new Error(translationsEn["pptx.export.errorNo2dContext"]);
  }
  const fps = 30;
  const stream = recordingCanvas.captureStream(fps);
  const recorder = new MediaRecorder(stream, {
    mimeType: pickSupportedMimeType([...WEBM_MIME_CANDIDATES]),
    videoBitsPerSecond: 5e6
  });
  const chunks = [];
  recorder.ondataavailable = (e) => {
    if (e.data.size > 0) {
      chunks.push(e.data);
    }
  };
  const recorderDone = new Promise((resolve, reject) => {
    recorder.onstop = () => resolve();
    recorder.onerror = (e) => reject(e);
  });
  recorder.start();
  for (let i = 0; i < slideCanvases.length; i++) {
    if (signal?.aborted) {
      recorder.stop();
      throw new DOMException("Export cancelled", "AbortError");
    }
    onRecordProgress?.(i, slideCanvases.length);
    const duration = slideTimingsMs?.[i] ?? slideDurationMs;
    ctx.clearRect(0, 0, recordingCanvas.width, recordingCanvas.height);
    ctx.drawImage(slideCanvases[i], 0, 0);
    const frameInterval = fpsToFrameIntervalMs(fps);
    const framesNeeded = segmentFrameCount(duration, fps);
    for (let f = 0; f < framesNeeded; f++) {
      if (signal?.aborted) {
        recorder.stop();
        throw new DOMException("Export cancelled", "AbortError");
      }
      ctx.drawImage(slideCanvases[i], 0, 0);
      await new Promise((r) => {
        setTimeout(r, frameInterval);
      });
    }
  }
  recorder.stop();
  await recorderDone;
  onProgress?.(totalSlides, totalSlides);
  return new Blob(chunks, { type: "video/webm" });
}

// src/viewer/utils/export-gif.ts
async function exportAllSlidesAsGif(slideStageRef, totalSlides, setActiveSlide, currentSlideIndex, options = {}) {
  const { scale = 0.5, slideDurationMs = 2e3, onProgress, signal } = options;
  const frames = [];
  for (let i = 0; i < totalSlides; i++) {
    if (signal?.aborted) {
      throw new DOMException("Export cancelled", "AbortError");
    }
    onProgress?.(i, totalSlides);
    setActiveSlide(i);
    await waitForRender(150);
    const stageEl = slideStageRef.current;
    if (!stageEl) {
      continue;
    }
    const canvas = await renderElementToCanvas(stageEl, scale);
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      continue;
    }
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    frames.push({
      imageData,
      width: canvas.width,
      height: canvas.height
    });
  }
  setActiveSlide(currentSlideIndex);
  if (frames.length === 0) {
    throw new Error(translationsEn["pptx.export.errorNoSlidesGif"]);
  }
  const gifBytes = encodeGif(frames, Math.round(slideDurationMs / 10));
  onProgress?.(totalSlides, totalSlides);
  const buf = new ArrayBuffer(gifBytes.length);
  new Uint8Array(buf).set(gifBytes);
  return new Blob([buf], { type: "image/gif" });
}

// src/viewer/utils/export-svg.ts
function injectFontFaces(svg, fontFaces) {
  if (!fontFaces.length) {
    return svg;
  }
  const safeFontFaces = fontFaces.filter((f) => {
    if (f.css.toLowerCase().includes("</style")) {
      console.warn(
        `[export-svg] Dropping @font-face entry for "${f.family}" containing "</style" - would break out of the <style> block.`
      );
      return false;
    }
    return true;
  });
  if (!safeFontFaces.length) {
    return svg;
  }
  const styleBlock = `<style type="text/css">${safeFontFaces.map((f) => f.css).join("\n")}</style>`;
  if (svg.includes("<defs>")) {
    return svg.replace("<defs>", `<defs>${styleBlock}`);
  }
  const closingBracket = svg.indexOf(">");
  if (closingBracket === -1) {
    return svg;
  }
  return `${svg.slice(0, closingBracket + 1)}<defs>${styleBlock}</defs>${svg.slice(closingBracket + 1)}`;
}
function exportAllSlidesToSvg(data, options = {}) {
  const { onProgress, embedFonts, fontFaces } = options;
  const svgOptions = {
    includeHidden: options.includeHidden,
    slideIndices: options.slideIndices,
    defaultFontFamily: options.defaultFontFamily,
    defaultFontSize: options.defaultFontSize
  };
  const results = [];
  const includeHidden = svgOptions.includeHidden ?? false;
  let processedCount = 0;
  for (let i = 0; i < data.slides.length; i++) {
    if (svgOptions.slideIndices && !svgOptions.slideIndices.includes(i)) {
      continue;
    }
    const slide = data.slides[i];
    if (slide.hidden && !includeHidden) {
      continue;
    }
    onProgress?.(processedCount, data.slides.length);
    let svg = SvgExporter.exportSlide(slide, data.width, data.height, svgOptions);
    if (embedFonts && fontFaces?.length) {
      svg = injectFontFaces(svg, fontFaces);
    }
    results.push(svg);
    processedCount++;
  }
  onProgress?.(processedCount, data.slides.length);
  return results;
}

